  1	/**
  2	 * Recomputes the usage counters that every `LimitCheck` compares against.
  3	 *
  4	 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
  5	 */
  6	import { getPlanLimits } from "@/config/plan-limits";
  7	import { emit, subscribe } from "@/lib/event-bus";
  8	import { assertOrgScope } from "@/lib/tenant";
  9	import * as orgRepo from "@/server/repositories/organization-repository";
 10	import * as usageRepo from "@/server/repositories/usage-repository";
 11	import { toIsoTimestamp } from "@/types/common";
 12	import type { OrgId } from "@/types/common";
 13	import type { Unsubscribe } from "@/types/event";
 14	import type { Actor } from "@/types/member";
 15	import type { OrganizationUsage } from "@/types/organization";
 16	
 17	/** Fraction of a quota at which the "approaching limit" event fires. */
 18	const WARN_THRESHOLD = 0.9;
 19	
 20	export async function getUsage(
 21	  actor: Actor,
 22	  orgId: OrgId,
 23	): Promise<OrganizationUsage> {
 24	  assertOrgScope(actor, orgId);
 25	  return usageRepo.getUsage(orgId);
 26	}
 27	
 28	/**
 29	 * Full recount from the source tables. Called by the rollup job and by every
 30	 * event that could have moved a counter — after recounting, the seat and
 31	 * project totals are checked against the plan so a breach surfaces as an
 32	 * event rather than waiting for the next write to be rejected.
 33	 */
 34	export async function recomputeUsage(
 35	  orgId: OrgId,
 36	): Promise<OrganizationUsage> {
 37	  const usage = await usageRepo.recomputeUsage(orgId);
 38	  const org = await orgRepo.findOrgById(orgId);
 39	  if (!org) return usage;
 40	
 41	  const limits = getPlanLimits(org.plan);
 42	
 43	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
 44	    await emit("billing.limit_exceeded", {
 45	      orgId,
 46	      actorId: null,
 47	      occurredAt: toIsoTimestamp(new Date()),
 48	      resource: "seats",
 49	      limit: limits.seats,
 50	      used: usage.seatsUsed,
 51	    });
 52	  }
 53	
 54	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
 55	    await emit("billing.limit_exceeded", {
 56	      orgId,
 57	      actorId: null,
 58	      occurredAt: toIsoTimestamp(new Date()),
 59	      resource: "projects",
 60	      limit: limits.projects,
 61	      used: usage.projectsUsed,
 62	    });
 63	  }
 64	
 65	  return usage;
 66	}
 67	
 68	/**
 69	 * Every event that changes a counted resource nudges the cache. The deltas are
 70	 * cheap; the periodic rollup is what corrects any drift they accumulate.
 71	 */
 72	export function registerUsageListeners(): Unsubscribe {
 73	  const offs: Unsubscribe[] = [
 74	    subscribe("issue.created", async (payload) => {
 75	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
 76	    }),
 77	    subscribe("issue.archived", async (payload) => {
 78	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
 79	    }),
 80	    subscribe("project.created", async (payload) => {
 81	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
 82	    }),
 83	    subscribe("project.archived", async (payload) => {
 84	      await usageRepo.incrementUsage(payload.orgId, {
 85	        projectsUsed: -1,
 86	        issuesUsed: -payload.issuesArchived,
 87	      });
 88	    }),
 89	    subscribe("member.joined", async (payload) => {
 90	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
 91	    }),
 92	    subscribe("member.removed", async (payload) => {
 93	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
 94	    }),
 95	  ];
 96	
 97	  return () => {
 98	    for (const off of offs) off();
 99	  };
100	}
  1	/**
  2	 * The `organization_usage` counters read by every plan-limit check.
  3	 */
  4	import { and, count, eq, isNull, sql } from "drizzle-orm";
  5	import {
  6	  attachments,
  7	  getDb,
  8	  issues,
  9	  members,
 10	  organizationUsage,
 11	  projects,
 12	} from "@/server/db";
 13	import { toIsoTimestamp } from "@/types/common";
 14	import { toUsage } from "./_mappers";
 15	import { brandId } from "./_mappers";
 16	import type { OrgId } from "@/types/common";
 17	import type { OrganizationUsage } from "@/types/organization";
 18	
 19	const BYTES_PER_MB = 1024 * 1024;
 20	
 21	/**
 22	 * Reads the cached counters, materialising a zeroed row the first time an org
 23	 * is asked about. A limit check must never fail because the rollup has not run.
 24	 */
 25	export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
 26	  const row = getDb()
 27	    .select()
 28	    .from(organizationUsage)
 29	    .where(eq(organizationUsage.orgId, orgId))
 30	    .get();
 31	
 32	  if (row) return toUsage(row);
 33	
 34	  const created = getDb()
 35	    .insert(organizationUsage)
 36	    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
 37	    .returning()
 38	    .get();
 39	
 40	  return toUsage(created);
 41	}
 42	
 43	/**
 44	 * Recounts every dimension from the source tables and rewrites the cache.
 45	 * Called by the rollup job and after any bulk change that would drift.
 46	 */
 47	export async function recomputeUsage(
 48	  orgId: OrgId,
 49	): Promise<OrganizationUsage> {
 50	  const db = getDb();
 51	
 52	  const seats = db
 53	    .select({ value: count() })
 54	    .from(members)
 55	    .where(
 56	      and(
 57	        eq(members.orgId, orgId),
 58	        eq(members.status, "active"),
 59	        isNull(members.archivedAt),
 60	      ),
 61	    )
 62	    .get();
 63	
 64	  const projectCount = db
 65	    .select({ value: count() })
 66	    .from(projects)
 67	    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
 68	    .get();
 69	
 70	  const issueCount = db
 71	    .select({ value: count() })
 72	    .from(issues)
 73	    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
 74	    .get();
 75	
 76	  const bytes = db
 77	    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
 78	    .from(attachments)
 79	    .where(eq(attachments.orgId, orgId))
 80	    .get();
 81	
 82	  const next = {
 83	    orgId,
 84	    seatsUsed: seats?.value ?? 0,
 85	    projectsUsed: projectCount?.value ?? 0,
 86	    issuesUsed: issueCount?.value ?? 0,
 87	    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
 88	    measuredAt: toIsoTimestamp(new Date()),
 89	  };
 90	
 91	  const row = db
 92	    .insert(organizationUsage)
 93	    .values(next)
 94	    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
 95	    .returning()
 96	    .get();
 97	
 98	  return toUsage(row);
 99	}
100	
101	/**
102	 * Cheap delta applied on the write path so a quota check right after a create
103	 * sees the new number without waiting for the rollup.
104	 */
105	export async function incrementUsage(
106	  orgId: OrgId,
107	  patch: Partial<
108	    Pick<
109	      OrganizationUsage,
110	      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
111	    >
112	  >,
113	): Promise<OrganizationUsage> {
114	  const current = await getUsage(orgId);
115	
116	  const row = getDb()
117	    .update(organizationUsage)
118	    .set({
119	      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
120	      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
121	      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
122	      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
123	      measuredAt: toIsoTimestamp(new Date()),
124	    })
125	    .where(eq(organizationUsage.orgId, orgId))
126	    .returning()
127	    .get();
128	
129	  return toUsage(row);
130	}
131	
132	/** The rollup job's work list: the oldest measurements first. */
133	export async function listOrgIdsForRollup(
134	  limit: number,
135	): Promise<readonly OrgId[]> {
136	  const rows = getDb()
137	    .select({ orgId: organizationUsage.orgId })
138	    .from(organizationUsage)
139	    .orderBy(organizationUsage.measuredAt)
140	    .limit(Math.max(1, limit))
141	    .all();
142	
143	  return rows.map((row) => brandId<OrgId>(row.orgId));
144	}
