  1	/**
  2	 * Plan-limit enforcement on the write paths.
  3	 *
  4	 * `PLAN_LIMITS` is the single source of the numbers and `wouldExceedLimit()`
  5	 * the single comparison; these cases prove the services actually consult them
  6	 * before writing, and that a pending invitation already holds its seat.
  7	 */
  8	import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
  9	
 10	vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
 11	// The only double left in this suite. `@/lib/rate-limit` is real everywhere
 12	// else, but these cases need to *choose* the verdict — the seat-quota refusal
 13	// has to be provably about seats and not about a bucket the previous case
 14	// happened to drain, and the throttling case needs a guaranteed denial.
 15	vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);
 16	
 17	import { getPlanLimits } from "@/config/plan-limits";
 18	import * as invitationRepo from "@/server/repositories/invitation-repository";
 19	import * as memberRepo from "@/server/repositories/member-repository";
 20	import * as billingService from "@/server/services/billing-service";
 21	import * as invitationService from "@/server/services/invitation-service";
 22	import * as projectService from "@/server/services/project-service";
 23	import * as usageService from "@/server/services/usage-service";
 24	import { rateLimitState } from "./_support/doubles/misc";
 25	import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
 26	import type { Tenant } from "./_support/fixtures";
 27	
 28	let cleanup: () => void;
 29	/** Free plan: 3 seats, 2 projects. The fixture seeds four members. */
 30	let free: Tenant;
 31	let growth: Tenant;
 32	
 33	beforeAll(async () => {
 34	  cleanup = await useTemporaryDatabase();
 35	  free = await createTenant("frugal", "free");
 36	  growth = await createTenant("growing", "growth");
 37	});
 38	
 39	afterAll(() => {
 40	  cleanup();
 41	  rateLimitState.allowed = true;
 42	});
 43	
 44	describe("seat quota on invite", () => {
 45	  it("rejects an invite once the plan's seats are taken", async () => {
 46	    expect(getPlanLimits("free").seats).toBe(3);
 47	    await expect(memberRepo.countActiveMembers(free.org.id)).resolves.toBe(4);
 48	
 49	    await expect(
 50	      invitationService.inviteMember(free.actors.owner, {
 51	        orgId: free.org.id,
 52	        email: "fifth@frugal.test",
 53	        role: "member",
 54	      }),
 55	    ).rejects.toThrow(/seats/i);
 56	  });
 57	
 58	  it("writes no invitation row when the quota rejects the batch", async () => {
 59	    await expect(
 60	      invitationRepo.countPendingInvitations(free.org.id),
 61	    ).resolves.toBe(0);
 62	  });
 63	
 64	  it("rejects a bulk invite as a whole rather than partially filling it", async () => {
 65	    const limits = getPlanLimits("growth");
 66	    expect(limits.seats).toBe(50);
 67	
 68	    const invites = Array.from({ length: 49 }, (_, index) => ({
 69	      email: `bulk-${index}@growing.test`,
 70	      role: "member" as const,
 71	    }));
 72	
 73	    await expect(
 74	      invitationService.inviteMembers(growth.actors.owner, {
 75	        orgId: growth.org.id,
 76	        invites,
 77	      }),
 78	    ).rejects.toThrow(/seats/i);
 79	
 80	    await expect(
 81	      invitationRepo.countPendingInvitations(growth.org.id),
 82	    ).resolves.toBe(0);
 83	  });
 84	
 85	  it("counts a pending invitation against the seat quota", async () => {
 86	    const before = await invitationRepo.countPendingInvitations(growth.org.id);
 87	
 88	    await invitationService.inviteMember(growth.actors.owner, {
 89	      orgId: growth.org.id,
 90	      email: "solo@growing.test",
 91	      role: "member",
 92	    });
 93	
 94	    await expect(
 95	      invitationRepo.countPendingInvitations(growth.org.id),
 96	    ).resolves.toBe(before + 1);
 97	  });
 98	
 99	  it("refuses the invite when the rate limiter says no", async () => {
100	    rateLimitState.allowed = false;
101	
102	    await expect(
103	      invitationService.inviteMember(growth.actors.owner, {
104	        orgId: growth.org.id,
105	        email: "throttled@growing.test",
106	        role: "member",
107	      }),
108	    ).rejects.toThrow(/rate limit/i);
109	
110	    rateLimitState.allowed = true;
111	  });
112	});
113	
114	describe("project quota", () => {
115	  it("rejects the project that would exceed the plan", async () => {
116	    expect(getPlanLimits("free").projects).toBe(2);
117	
118	    // The fixture already created one project; this fills the plan.
119	    await projectService.createProject(free.actors.owner, {
120	      orgId: free.org.id,
121	      name: "Second",
122	      slug: "second",
123	      key: "SEC",
124	      description: null,
125	      visibility: "org",
126	      leadId: null,
127	      color: "#6366f1",
128	      targetDate: null,
129	    });
130	
131	    await expect(
132	      projectService.createProject(free.actors.owner, {
133	        orgId: free.org.id,
134	        name: "Third",
135	        slug: "third",
136	        key: "THR",
137	        description: null,
138	        visibility: "org",
139	        leadId: null,
140	        color: "#6366f1",
141	        targetDate: null,
142	      }),
143	    ).rejects.toThrow(/projects/i);
144	  });
145	});
146	
147	describe("BillingService.checkLimit", () => {
148	  it("reports the plan, the usage and whether one more would breach", async () => {
149	    await usageService.recomputeUsage(free.org.id);
150	
151	    const check = await billingService.checkLimit(free.org.id, "seats");
152	
153	    expect(check).toMatchObject({
154	      resource: "seats",
155	      plan: "free",
156	      limit: 3,
157	      used: 4,
158	      remaining: 0,
159	      exceeded: true,
160	    });
161	  });
162	
163	  it("leaves an org with room under its limit", async () => {
164	    await usageService.recomputeUsage(growth.org.id);
165	
166	    const check = await billingService.checkLimit(growth.org.id, "seats");
167	    expect(check.exceeded).toBe(false);
168	    expect(check.remaining).toBeGreaterThan(0);
169	  });
170	});
  1	"use server";
  2	
  3	/**
  4	 * Accepts an invitation token and creates the membership.
  5	 *
  6	 * Owner D. Runs for a signed-in user who is *not yet* a member of the target
  7	 * org, so there is no `Actor` to resolve and the action cannot use
  8	 * `withAction()`. The seat quota is re-checked at acceptance time because the
  9	 * organization may have filled up since the invitation was sent.
 10	 *
 11	 * Must call (do not reimplement): acceptInvitationTokenSchema, getPlanLimits
 12	 */
 13	
 14	import { PlanLimitError, UnauthorizedActionError } from "@/actions/_lib/action-errors";
 15	import { getPlanLimits } from "@/config/plan-limits";
 16	import { toActionResult } from "@/lib/errors";
 17	import { getSessionPrincipal } from "@/lib/session";
 18	import { acceptInvitationTokenSchema } from "@/schemas/invitation";
 19	import { acceptInvitation } from "@/server/services/invitation-service";
 20	import { resolveActor } from "@/server/services/member-service";
 21	import { getOrganizationSummary } from "@/server/services/organization-service";
 22	import type { ActionResult } from "@/types/api";
 23	import type { Member } from "@/types/member";
 24	
 25	export async function acceptInvitationAction(raw: unknown): Promise<ActionResult<Member>> {
 26	  const parsed = acceptInvitationTokenSchema.safeParse(raw);
 27	  if (!parsed.success) {
 28	    return toActionResult(parsed.error);
 29	  }
 30	
 31	  try {
 32	    const principal = await getSessionPrincipal();
 33	    if (principal === null) {
 34	      throw new UnauthorizedActionError("Sign in before accepting an invitation.");
 35	    }
 36	
 37	    const member = await acceptInvitation(principal.userId, parsed.data);
 38	    await assertSeatAvailable(member);
 39	
 40	    return { ok: true, data: member, submittedAt: new Date().toISOString() };
 41	  } catch (error) {
 42	    return toActionResult(error);
 43	  }
 44	}
 45	
 46	/**
 47	 * Confirms the newly created membership still fits the plan. Reading usage
 48	 * requires an actor inside the org, which only exists once the membership row
 49	 * has been written — hence the check runs after `acceptInvitation`.
 50	 */
 51	async function assertSeatAvailable(member: Member): Promise<void> {
 52	  const actor = await resolveActor(member.userId, member.orgId);
 53	  if (actor === null) {
 54	    throw new UnauthorizedActionError("That invitation is no longer valid.");
 55	  }
 56	
 57	  const summary = await getOrganizationSummary(actor, member.orgId);
 58	  const limits = getPlanLimits(summary.organization.plan);
 59	  if (summary.usage.seatsUsed > limits.seats) {
 60	    throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
 61	  }
 62	}
  1	/**
  2	 * Pending invitations.
  3	 *
  4	 * Owner D. Read-only listing plus revoke. `InvitationService` exposes the
  5	 * lifecycle verbs but no listing, so the page reads
  6	 * `listPendingInvitations()` from the repository directly — the query is
  7	 * already org-scoped and there is no rule for a service to add on top of it.
  8	 *
  9	 * Must call (do not reimplement): can
 10	 */
 11	
 12	import { notFound } from "next/navigation";
 13	import type { Metadata } from "next";
 14	import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
 15	import { InvitationList } from "@/components/domain/member/invitation-list";
 16	import { EmptyState } from "@/components/ui/empty-state";
 17	import { can } from "@/lib/permissions";
 18	import { listPendingInvitations } from "@/server/repositories/invitation-repository";
 19	import { revokeInvitation } from "@/server/services/invitation-service";
 20	import type { InvitationId } from "@/types/common";
 21	import { loadTenantContext } from "../../../_lib/tenant-context";
 22	
 23	type PageParams = { orgSlug: string };
 24	
 25	export const dynamic = "force-dynamic";
 26	
 27	export const metadata: Metadata = {
 28	  title: "Pending invitations",
 29	};
 30	
 31	export default async function Page(props: {
 32	  params: Promise<PageParams>;
 33	  searchParams: Promise<Record<string, string | string[] | undefined>>;
 34	}) {
 35	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
 36	  const { orgSlug } = await props.params;
 37	  await props.searchParams;
 38	
 39	  const { org, actor } = await loadTenantContext(orgSlug);
 40	
 41	  const mayRead = can(actor, "member:read", {
 42	    kind: "member",
 43	    orgId: org.id,
 44	    memberId: PENDING_MEMBER_ID,
 45	    targetUserId: actor.userId,
 46	    targetRole: actor.role,
 47	  });
 48	  if (!mayRead) {
 49	    notFound();
 50	  }
 51	
 52	  const invitations = await listPendingInvitations(org.id);
 53	
 54	  async function revoke(invitationId: InvitationId): Promise<void> {
 55	    "use server";
 56	    await revokeInvitation(actor, invitationId);
 57	  }
 58	
 59	  return (
 60	    <div className="space-y-8">
 61	      <header>
 62	        <h1 className="text-xl font-semibold tracking-tight">
 63	          Pending invitations
 64	        </h1>
 65	        <p className="mt-1 text-sm text-slate-600">
 66	          Invitations that have been sent but not yet accepted. Each one still
 67	          counts against the seat quota.
 68	        </p>
 69	      </header>
 70	
 71	      {invitations.length === 0 ? (
 72	        <EmptyState
 73	          title="No invitations outstanding"
 74	          description="Everybody who was invited has either joined or been revoked."
 75	        />
 76	      ) : (
 77	        <InvitationList
 78	          invitations={invitations}
 79	          actor={actor}
 80	          onRevoke={revoke}

