  2	
  3	/**
  4	 * Accepts an invitation token and creates the membership.
  5	 *
  6	 * Owner D. Runs for a signed-in user who is *not yet* a member of the target
  7	 * org, so there is no `Actor` to resolve and the action cannot use
  8	 * `withAction()`. The seat quota is re-checked at acceptance time because the
  9	 * organization may have filled up since the invitation was sent.
 10	 *
 11	 * Must call (do not reimplement): acceptInvitationTokenSchema, getPlanLimits
 12	 */
 13	
 14	import { PlanLimitError, UnauthorizedActionError } from "@/actions/_lib/action-errors";
 15	import { getPlanLimits } from "@/config/plan-limits";
 16	import { toActionResult } from "@/lib/errors";
 17	import { getSessionPrincipal } from "@/lib/session";
 18	import { acceptInvitationTokenSchema } from "@/schemas/invitation";
 19	import { acceptInvitation } from "@/server/services/invitation-service";
 20	import { resolveActor } from "@/server/services/member-service";
 21	import { getOrganizationSummary } from "@/server/services/organization-service";
 22	import type { ActionResult } from "@/types/api";
 23	import type { Member } from "@/types/member";
 24	
 25	export async function acceptInvitationAction(raw: unknown): Promise<ActionResult<Member>> {
 26	  const parsed = acceptInvitationTokenSchema.safeParse(raw);
 27	  if (!parsed.success) {
 28	    return toActionResult(parsed.error);
 29	  }
 30	
 31	  try {
 32	    const principal = await getSessionPrincipal();
 33	    if (principal === null) {
 34	      throw new UnauthorizedActionError("Sign in before accepting an invitation.");
 35	    }
 36	
 37	    const member = await acceptInvitation(principal.userId, parsed.data);
 38	    await assertSeatAvailable(member);
 39	
 40	    return { ok: true, data: member, submittedAt: new Date().toISOString() };
 41	  } catch (error) {
 42	    return toActionResult(error);
 43	  }
 44	}
 45	
 46	/**
 47	 * Confirms the newly created membership still fits the plan. Reading usage
 48	 * requires an actor inside the org, which only exists once the membership row
 49	 * has been written — hence the check runs after `acceptInvitation`.
 50	 */
 51	async function assertSeatAvailable(member: Member): Promise<void> {
 52	  const actor = await resolveActor(member.userId, member.orgId);
 53	  if (actor === null) {
 54	    throw new UnauthorizedActionError("That invitation is no longer valid.");
 55	  }
 56	
 57	  const summary = await getOrganizationSummary(actor, member.orgId);
 58	  const limits = getPlanLimits(summary.organization.plan);
 59	  if (summary.usage.seatsUsed > limits.seats) {
 60	    throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
 61	  }
 62	}
  1	/**
  2	 * Pending invitations.
  3	 *
  4	 * Owner D. Read-only listing plus revoke. `InvitationService` exposes the
  5	 * lifecycle verbs but no listing, so the page reads
  6	 * `listPendingInvitations()` from the repository directly — the query is
  7	 * already org-scoped and there is no rule for a service to add on top of it.
  8	 *
  9	 * Must call (do not reimplement): can
 10	 */
 11	
 12	import { notFound } from "next/navigation";
 13	import type { Metadata } from "next";
 14	import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
 15	import { InvitationList } from "@/components/domain/member/invitation-list";
 16	import { EmptyState } from "@/components/ui/empty-state";
 17	import { can } from "@/lib/permissions";
 18	import { listPendingInvitations } from "@/server/repositories/invitation-repository";
 19	import { revokeInvitation } from "@/server/services/invitation-service";
 20	import type { InvitationId } from "@/types/common";
 21	import { loadTenantContext } from "../../../_lib/tenant-context";
 22	
 23	type PageParams = { orgSlug: string };
 24	
 25	export const dynamic = "force-dynamic";
 26	
 27	export const metadata: Metadata = {
 28	  title: "Pending invitations",
 29	};
 30	
 31	export default async function Page(props: {
 32	  params: Promise<PageParams>;
 33	  searchParams: Promise<Record<string, string | string[] | undefined>>;
 34	}) {
 35	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
 36	  const { orgSlug } = await props.params;
 37	  await props.searchParams;
 38	
 39	  const { org, actor } = await loadTenantContext(orgSlug);
 40	
 41	  const mayRead = can(actor, "member:read", {
 42	    kind: "member",
 43	    orgId: org.id,
 44	    memberId: PENDING_MEMBER_ID,
 45	    targetUserId: actor.userId,
 46	    targetRole: actor.role,
 47	  });
 48	  if (!mayRead) {
 49	    notFound();
 50	  }
 51	
 52	  const invitations = await listPendingInvitations(org.id);
 53	
 54	  async function revoke(invitationId: InvitationId): Promise<void> {
 55	    "use server";
 56	    await revokeInvitation(actor, invitationId);
 57	  }
 58	
 59	  return (
 60	    <div className="space-y-8">
 61	      <header>
 62	        <h1 className="text-xl font-semibold tracking-tight">
 63	          Pending invitations
 64	        </h1>
 65	        <p className="mt-1 text-sm text-slate-600">
 66	          Invitations that have been sent but not yet accepted. Each one still
 67	          counts against the seat quota.
 68	        </p>
 69	      </header>
 70	
 71	      {invitations.length === 0 ? (
 72	        <EmptyState
 73	          title="No invitations outstanding"
 74	          description="Everybody who was invited has either joined or been revoked."
 75	        />
 76	      ) : (
 77	        <InvitationList
 78	          invitations={invitations}
 79	          actor={actor}
 80	          onRevoke={revoke}

