/**
 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
 */
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { isLive } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
import type { InvitationId, OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";
import type { Actor, Invitation, Member, Role } from "@/types/member";

/** Token bucket protecting the invite mailer from being used as a spam relay. */
const INVITE_BUCKET = "member:invite";

/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

/** One address and the role it is offered. */
interface InviteRequest {
  readonly email: string;
  readonly role: Role;
}

export async function inviteMember(
  actor: Actor,
  input: InviteMemberInput,
): Promise<Invitation> {
  const [invitation] = await inviteMembers(actor, {
    orgId: input.orgId,
    invites: [{ email: input.email, role: input.role }],
  });

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  return issueInvitations(actor, input.orgId, input.invites, null);
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 * The token only opens the invitation for the address it was sent to.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }

  const now = toIsoTimestamp(new Date());
  if (invitation.expiresAt <= now) {
    throw new Error("That invitation has expired");
  }

  await requireLiveOrg(invitation.orgId);

  const account = requireFound(await userRepo.findUserById(userId), "User", userId);
  if (account.email.toLowerCase() !== invitation.email.toLowerCase()) {
    throw new Error("That invitation was sent to a different email address");
  }

  const existing = await memberRepo.findMembershipRecord(invitation.orgId, userId);
  if (existing !== null && isLive(existing)) {
    // Already a member through another invitation: this one is used up and
    // the seat count does not change.
    await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);
    return existing;
  }

  // A former member gets their original row back rather than a second one,
  // which the (org, user) unique index would refuse anyway.
  const member =
    existing === null
      ? await memberRepo.insertMember(
          invitation.orgId,
          userId,
          invitation.role,
          invitation.invitedBy,
        )
      : await memberRepo.reinstateMember(invitation.orgId, existing.id, {
          role: invitation.role,
          invitedBy: invitation.invitedBy,
          joinedAt: now,
        });

  await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately. The
 * replacement keeps the address and the role, and a re-send of an expired
 * invitation is how it gets a fresh 14-day window.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo
      .listPendingInvitations(actor.orgId)
      .then((rows) => rows.find((row) => row.id === invitationId) ?? null),
    "Invitation",
    invitationId,
  );

  const [invitation] = await issueInvitations(
    actor,
    actor.orgId,
    [{ email: previous.email, role: previous.role }],
    previous,
  );

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

/**
 * Issues one invitation per request, or none at all: every refusal is decided
 * before the first write. `replacing` is the outstanding invitation a re-send
 * withdraws. It does not block the new one, and if it is still unexpired it
 * gives its seat back before the new one takes it.
 */
async function issueInvitations(
  actor: Actor,
  orgId: OrgId,
  requests: readonly InviteRequest[],
  replacing: Invitation | null,
): Promise<readonly Invitation[]> {
  assertNoRepeatedAddress(requests);

  const verdict = await consumeRateLimit(orgId, INVITE_BUCKET, requests.length);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await requireLiveOrg(orgId);

  for (const request of requests) {
    if ((await memberRepo.findLiveMemberByEmail(orgId, request.email)) !== null) {
      throw new Error(`${request.email} is already a member of this workspace`);
    }

    const clashing = (
      await invitationRepo.findPendingInvitationsByEmail(orgId, request.email)
    ).filter((invitation) => invitation.id !== replacing?.id);
    if (clashing.length > 0) {
      throw new Error(`${request.email} already has a pending invitation`);
    }
  }

  const replacedHoldsSeat =
    replacing !== null && replacing.expiresAt > toIsoTimestamp(new Date());
  const seatsUsed =
    (await memberRepo.countActiveMembers(orgId)) +
    (await invitationRepo.countPendingInvitations(orgId)) -
    (replacedHoldsSeat ? 1 : 0);

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, requests.length)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  if (replacing !== null) {
    await invitationRepo.revokeInvitation(orgId, replacing.id);
  }

  const invitations: Invitation[] = [];

  for (const request of requests) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      {
        orgId,
        email: request.email,
        role: request.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: request.email,
      role: request.role,
    });
  }

  return invitations;
}

/** A batch that names one address twice is refused whole, whatever the letter case. */
function assertNoRepeatedAddress(requests: readonly InviteRequest[]): void {
  const seen = new Set<string>();
  for (const request of requests) {
    const address = request.email.toLowerCase();
    if (seen.has(address)) {
      throw new Error(`${request.email} is named more than once in this invite`);
    }
    seen.add(address);
  }
}

/** A deleted workspace neither sends nor accepts invitations. */
async function requireLiveOrg(orgId: OrgId): Promise<Organization> {
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  if (!isLive(org)) throw new Error("That workspace has been deleted");
  return org;
}

