import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);

import { eq } from "drizzle-orm";
import { hashToken } from "@/lib/hash";
import { getDb, sessions } from "@/server/db";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as digestService from "@/server/services/digest-service";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import { resolveActor } from "@/server/services/member-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import { rateLimitState } from "./_support/doubles/misc";
import { toIsoTimestamp } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
  rateLimitState.allowed = true;
});

const DAY = 24 * 60 * 60 * 1000;

async function seed(tenant: Awaited<ReturnType<typeof createTenant>>, email: string, role: "admin" | "member" | "viewer", raw: string, days = 14) {
  return invitationRepo.insertInvitation(
    tenant.org.id,
    { orgId: tenant.org.id, email, role, expiresInDays: days },
    tenant.userIds.owner,
    hashToken(raw),
  );
}

describe("verify invitations", () => {
  it("rejoin reinstates the former member row", async () => {
    const t = await createTenant("v-rejoin", "growth");
    const before = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: before!.id });
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(3);

    await seed(t, "member@v-rejoin.test", "viewer", "r".repeat(32));
    const m = await invitationService.acceptInvitation(t.userIds.member, { token: "r".repeat(32) });

    expect(m.id).toBe(before!.id);
    expect(m.role).toBe("viewer");
    expect(m.status).toBe("active");
    expect(m.archivedAt).toBeNull();
    expect(m.invitedBy).toBe(t.userIds.owner);
    expect(m.joinedAt).not.toBeNull();
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
    expect(await resolveActor(t.userIds.member, t.org.id)).not.toBeNull();
  });

  it("a new account accepting becomes an active, resolvable member", async () => {
    const t = await createTenant("v-accept", "growth");
    const user = await userRepo.insertUser({ email: "Newbie@V-Accept.test", name: "N", passwordHash: "x" });
    await seed(t, "newbie@v-accept.test", "admin", "n".repeat(32));
    const m = await invitationService.acceptInvitation(user.id, { token: "n".repeat(32) });
    expect(m.status).toBe("active");
    expect(m.role).toBe("admin");
    expect(await resolveActor(user.id, t.org.id)).toMatchObject({ role: "admin" });
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(5);
    // accepted invitation is used up
    await expect(invitationService.acceptInvitation(user.id, { token: "n".repeat(32) })).rejects.toThrow(/already been accepted/);
  });

  it("expiry is in days and a pending invite holds one seat", async () => {
    const t = await createTenant("v-expiry", "growth");
    const inv = await invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "a@v-expiry.test", role: "member" });
    const ms = Date.parse(inv.expiresAt) - Date.now();
    expect(ms).toBeGreaterThan(13.99 * DAY);
    expect(ms).toBeLessThan(14.01 * DAY);

    const pending = await invitationRepo.countPendingInvitations(t.org.id);
    expect(pending).toBe(1);
    await invitationService.revokeInvitation(t.actors.owner, inv.id);
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(0);
  });

  it("expired invitations do not hold seats", async () => {
    const t = await createTenant("v-expired-seat", "growth");
    await seed(t, "old@v-expired-seat.test", "member", "e".repeat(32), -1);
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(0);
  });

  it("refuses members, pending addresses and repeats in a batch, case-insensitively", async () => {
    const t = await createTenant("v-dupe", "growth");
    await expect(
      invitationService.inviteMembers(t.actors.owner, {
        orgId: t.org.id,
        invites: [
          { email: "fresh@v-dupe.test", role: "member" },
          { email: "FRESH@v-dupe.test", role: "member" },
        ],
      }),
    ).rejects.toThrow();
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(0);

    await invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "pend@v-dupe.test", role: "member" });
    await expect(
      invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "PEND@v-dupe.test", role: "member" }),
    ).rejects.toThrow(/pending/);
    await expect(
      invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "MEMBER@v-dupe.test", role: "member" }),
    ).rejects.toThrow(/already a member/);
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(1);
  });

  it("a former member can be invited again, and so can an expired or revoked address", async () => {
    const t = await createTenant("v-reinvite", "growth");
    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: member!.id });
    await expect(
      invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "member@v-reinvite.test", role: "member" }),
    ).resolves.toBeDefined();

    await seed(t, "exp@v-reinvite.test", "member", "x".repeat(32), -1);
    await expect(
      invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "exp@v-reinvite.test", role: "member" }),
    ).resolves.toBeDefined();
  });

  it("refuses an accept by anyone but the invited address and leaves it pending", async () => {
    const t = await createTenant("v-forward", "growth");
    await seed(t, "invitee@v-forward.test", "admin", "f".repeat(32));
    const other = await userRepo.insertUser({ email: "other@v-forward.test", name: "O", passwordHash: "x" });
    await expect(invitationService.acceptInvitation(other.id, { token: "f".repeat(32) })).rejects.toThrow(/different email/);
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(1);

    const invitee = await userRepo.insertUser({ email: "Invitee@V-Forward.test", name: "I", passwordHash: "x" });
    const m = await invitationService.acceptInvitation(invitee.id, { token: "f".repeat(32) });
    expect(m.role).toBe("admin");
  });

  it("resend keeps the role, works after expiry, and withdraws the old link", async () => {
    const t = await createTenant("v-resend", "growth");
    const first = await invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "r@v-resend.test", role: "admin" });
    const again = await invitationService.resendInvitation(t.actors.owner, first.id);
    expect(again.role).toBe("admin");
    expect(again.email).toBe("r@v-resend.test");
    expect(again.expiresAt > first.expiresAt || again.expiresAt >= first.expiresAt).toBe(true);
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(1);

    const stale = await seed(t, "late@v-resend.test", "viewer", "l".repeat(32), -1);
    const renewed = await invitationService.resendInvitation(t.actors.owner, stale.id);
    expect(renewed.role).toBe("viewer");
    expect(Date.parse(renewed.expiresAt)).toBeGreaterThan(Date.now());
  });

  it("refuses to accept into a deleted workspace", async () => {
    const t = await createTenant("v-deleted", "growth");
    await seed(t, "gone@v-deleted.test", "member", "d".repeat(32));
    const user = await userRepo.insertUser({ email: "gone@v-deleted.test", name: "G", passwordHash: "x" });
    await orgRepo.archiveOrg(t.org.id);
    await expect(invitationService.acceptInvitation(user.id, { token: "d".repeat(32) })).rejects.toThrow(/deleted/);
  });

  it("removed members get no notifications and no digest, and rejoin restores them", async () => {
    const t = await createTenant("v-notify", "growth");
    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.member, kind: "issue_assigned", inApp: true, email: true, digestOnly: true });
    expect(await digestService.listDigestRecipients(t.org.id)).toContain(t.userIds.member);

    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: member!.id });

    expect(await digestService.listDigestRecipients(t.org.id)).not.toContain(t.userIds.member);
    const payload = { title: "t", body: "b", href: "/x", actorId: t.userIds.owner };
    expect(await notify(t.org.id, "issue_assigned", [t.userIds.member], payload)).toHaveLength(0);

    await seed(t, "member@v-notify.test", "member", "n".repeat(32));
    await invitationService.acceptInvitation(t.userIds.member, { token: "n".repeat(32) });
    expect(await digestService.listDigestRecipients(t.org.id)).toContain(t.userIds.member);
    expect(await notify(t.org.id, "issue_assigned", [t.userIds.member], payload)).toHaveLength(1);
  });

  it("removal clears only that member's sessions on that workspace", async () => {
    const t = await createTenant("v-session", "growth");
    const other = await createTenant("v-session-other", "growth");
    const expiresAt = toIsoTimestamp(new Date(Date.now() + DAY));
    await sessionRepo.createSession(t.userIds.member, hashToken("s1"), expiresAt);
    await sessionRepo.createSession(t.userIds.member, hashToken("s2"), expiresAt);
    for (const token of ["s1", "s2"]) {
      const row = getDb().select().from(sessions).where(eq(sessions.tokenHash, hashToken(token))).get();
      await sessionRepo.setActiveOrg(row!.id as never, t.org.id);
    }
    const row3 = getDb().select().from(sessions).where(eq(sessions.tokenHash, hashToken("s2"))).get();
    expect(row3?.activeOrgId).toBe(t.org.id);

    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: member!.id });

    const s1 = await sessionRepo.findSessionByTokenHash(hashToken("s1"));
    expect(s1?.activeOrgId).toBeNull();
    expect(other.org.id).not.toBe(t.org.id);
  });
});

