import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import { resolveActor } from "@/server/services/member-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import { rateLimitState } from "./_support/doubles/misc";
import { toIsoTimestamp } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
  rateLimitState.allowed = true;
});

const DAY = 24 * 60 * 60 * 1000;

async function seed(tenant: Awaited<ReturnType<typeof createTenant>>, email: string, role: "admin" | "member" | "viewer", raw: string, days = 14) {
  return invitationRepo.insertInvitation(
    tenant.org.id,
    { orgId: tenant.org.id, email, role, expiresInDays: days },
    tenant.userIds.owner,
    hashToken(raw),
  );
}

