    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: before!.id });
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(3);

    await seed(t, "member@v-rejoin.test", "viewer", "r".repeat(32));
