    expect(m.id).toBe(before!.id);
    expect(m.role).toBe("viewer");
    expect(m.status).toBe("active");
    expect(m.archivedAt).toBeNull();
    expect(m.invitedBy).toBe(t.userIds.owner);
    expect(m.joinedAt).not.toBeNull();
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
    expect(await resolveActor(t.userIds.member, t.org.id)).not.toBeNull();
  });

