    expect(await notify(t.org.id, "issue_assigned", [t.userIds.member], payload)).toHaveLength(1);
  });

  it("removal clears only that member's sessions on that workspace", async () => {
    const t = await createTenant("v-session", "growth");
    const other = await createTenant("v-session-other", "growth");
    const expiresAt = toIsoTimestamp(new Date(Date.now() + DAY));
